WITH demo("id", "couple_name", "content", "rating", "sort_order", "created_at") AS (VALUES (null, '许佳 & 周航', '拍摄过程特别轻松，摄影师很会引导，我们就像在约会一样。成片的光线和色调超出预期，朋友圈被疯狂点赞！', 5, 1, (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))), (null, '小鱼 & 阿哲', '从选套系到拿到底片，顾问全程耐心解答，没有任何隐形消费。化妆师手艺很好，妈妈看到照片时红了眼眶。', 5, 2, (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))), (null, 'Jessica & Ryan', '中式主题的服装和布景很有质感，修图自然，没有过度磨皮。非常推荐给喜欢真实感的新人。', 5, 3, (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))), (null, '晓晓 & 明轩', '婚礼跟拍很细致，宾客互动的抓拍特别多，现在每次翻相册都会笑出声，谢谢拾光记录下我们的婚礼。', 5, 4, (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))))
insert into "testimonials" ("id", "couple_name", "content", "rating", "sort_order", "created_at") SELECT * FROM demo WHERE NOT EXISTS (SELECT 1 FROM testimonials);

WITH demo("id", "name", "title", "years", "bio", "sort_order") AS (VALUES (null, '陈墨', '首席摄影师', 12, '擅长自然光人像与纪实风格，作品多次入选国内婚纱摄影大赛。相信每一次快门，都是为了还原最真实的爱。', 1), (null, '林小雨', '资深摄影师', 8, '专注韩式清新与户外外景，镜头下的情绪温柔细腻，是许多新人心中的首选摄影师。', 2), (null, '周延', '婚礼纪实摄影师', 9, '累计拍摄数百场婚礼，擅长捕捉仪式中的情绪与细节，节奏把控稳，抓拍率高。', 3))
